export function mapPreference(preference) {
  const id = normalizeLocaleId(preference);
  if (!id) return null;
  const primary = id.split('-')[0].toLowerCase();
  if (primary === 'zh') return 'zh-CN';
  if (primary === 'en') return 'en';
