anguage.mjs && node scripts/verify-mirror.mjs && node scripts/verify-client.mjs && node scripts/verify-dispose.mjs && node scripts/verify-host-api.mjs && node scripts/verify-manifest.mjs && bash scripts/verify-checklist.sh\",\n    \"prepublishOnly\": \"node scripts/verify-release.mjs\",\n    \"verify:release\": \"node scripts/verify-release.mjs --verify\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"chinese\",\n    \"language\",\n    \"locale\",\n    \"system-prompt\",\n    \"i18n\"\n  ],\n  \"author\": {\n    \"name\": \"sunjingzhi\",\n    \"email\": \"dlyh@vip.qq.com\",\n    \"url\": \"https://github.com/58fly\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/58fly/dsh-language-guard.git\"\n  },\n  \"homepage\": \"https://github.com/58fly/dsh-language-guard#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/58fly/dsh-language-guard/issues\"\n  }\n}\n"
