      "path": "lib/state.js",
      "content": "/**\n * 运行时状态与配置值规范化。\n *\n * 本模块**不持有轮次计数**：D 档的 `turn` / `step` 直接来自\n * `agent/pre-step` 的 waterfall payload（01-mechanism.md 6.2、8.3），\n * 重启或恢复后仍然连续，不需要插件自己数。\n *\n * 这里只保存两类东西：\n * 1. `/language` 命令设置的内存覆盖值（不写配置、不落盘）；\n * 2. 配置值的规范化与兜底（schema 校验之外的二次防线）。\n *\n * 语言解析的**纯函数**部分在 `lib/language.js`（可单测），本模块只负责把\n * 内存覆盖值与它串起来。\n */\n\nimport { resolveTargetLanguage } from './language.js';\n\n/** 合法档位 */\nexport const STRENGTHS = ['B', 'C', 'D'];\n\n/** 默认档位：强化（01-mechanism.md 第 5 节） */\nexport const DEFAULT_STRENGTH = 'C';\n\n/** 注入间隔的取值范围与默认值（01-mechanism.md 4.1） */\nexport const MIN_INTERVAL = 3;\nexport const MAX_INTERVAL = 50;\nexport const DEFAULT_INTERVAL = 8;\n\n/** 默认目标语言 */\nexport const DEFAULT_LANGUAGE = 'zh-CN';\n\n/** `/language` 命令的内存覆盖值；null 表示未覆盖，走配置值 */\nlet languageOverride = null;\n\n/**\n * 设置 `/language` 的内存覆盖值。\n * @param {string} code BCP-47 语言标签\n */\nexport function setLanguageOverride(code) {\n  languageOverride = typeof code === 'string' && code.trim() ? code.trim() : null;\n}\n\n/** 清除 `/language` 的内存覆盖值，回到配置里的 targetLanguage。 */\nexport function clearLanguageOverride() {\n  languageOverride = null;\n}\n\n/** 读取 `/language` 的内存覆盖值（未设置时为 null）。 */\nexport function getLanguageOverride() {\n  return languageOverride;\n}\n\n/**\n * 解析当前生效的目标语言。\n *\n * 优先级（0.2.0）：\n * 1. `/language` 命令的内存覆盖值 —— 两种模式下都最优先，且不写配置；\n * 2. 自动模式：`mapPreference(界面语言) ?? targetLanguage`；\n * 3. 手动模式：`targetLanguage`；\n * 4. 兜底：`DEFAULT_LANGUAGE`。\n *\n * 不传 `options` 时行为与 0.1.x 完全一致（纯配置值），因此既有调用点无需改动。\n *\n * @param {string | undefined} configured 配置里的 targetLanguage\n * @param {{ mode?: unknown, preference?: unknown }} [options]\n *   `mode` 是原始的 `languageMode` 值（可为空串），三态判定在 `lib/language.js` 内完成。\n */\nexport function resolveLanguage(configured, options) {\n  if (languageOverride) return languageOverride;\n  const raw = typeof configured === 'string' ? configured.trim() : '';\n  if (options && typeof options === 'object') {\n    return resolveTargetLanguage({\n      mode: options.mode,\n      preference: options.preference,\n      fallback: raw || DEFAULT_LANGUAGE,\n      defaultLanguage: DEFAULT_LANGUAGE,\n    });\n  }\n  return raw || DEFAULT_LANGUAGE;\n}\n\n/**\n * 规范化档位：接受大小写，非法值回退默认档。\n * @param {unknown} raw\n * @returns {{ value: 'B' | 'C' | 'D', valid: boolean }}\n */\nexport function normalizeStrength(raw) {\n  const text = typeof raw === 'string' ? raw.trim().toUpperCase() : '';\n  if (STRENGTHS.includes(text)) return { value: text, valid: true };\n  return { value: DEFAULT_STRENGTH, valid: false };\n}\n\n/**\n * 规范化注入间隔：取整并夹到 3–50，非法值回退默认值。\n * @param {unknown} raw\n * @returns {{ value: number, valid: boolean }}\n */\nexport function normalizeInterval(raw) {\n  const number = typeof raw === 'number' ? raw : Number(raw);\n  if (!Number.isFinite(number)) return { value: DEFAULT_INTERVAL, valid: false };\n  const rounded = Math.round(number);\n  if (rounded < MIN_INTERVAL || rounded > MAX_INTERVAL) {\n    return { value: Math.min(MAX_INTERVAL, Math.max(MIN_INTERVAL, rounded)), valid: false };\n  }\n  return { value: rounded, valid: true };\n}\n\n/**\n * 规范化布尔值：只认真正的布尔，其余按默认 true 处理。\n * @param {unknown} raw\n */\nexport function normalizeBoolean(raw) {\n  return typeof raw === 'boolean' ? raw : true;\n}\n\n/**\n * 规范化自由文本字段（extraRules / overrideHead）：非字符串按空串处理。\n * @param {unknown} raw\n */\nexport function normalizeText(raw) {\n  return typeof raw === 'string' ? raw : '';\n}\n"
    },
    {
      "path": "lib/language.js",
      "content": "/**\n * 语言解析：把「界面语言」映射成 `targetLanguage`，并处理自动 / 手动两种模式。\n *\n * 本模块是**纯函数模块**：不 import 任何 ctx、不读磁盘、不碰配置对象，\n * 所有输入显式传入。这样验收脚本可以直接 `import` 后断言每一条映射规则\n * （`scripts/verify-language.mjs`），不需要伪造 DSH 运行时。\n *\n * 真源：docs/research/04-auto-language.md 第 7.3 / 8.3 / 9.3 节，\n * 以及票 #14 的三条裁决（0.2.0 只做路径 A、映射只四条、解析器必须纯函数）。\n *\n * ## 0.2.0 的信号范围（有意为之的窄）\n *\n * Host 侧唯一可靠信号是 `settings.describe()` 里 `ns === 'locale'` 的\n * `value.preference`。系统语言（`osLanguages`）只有 Client 能拿到，而路径 B\n * （Client 回写检测值）在 0.2.0 **完全不实现**，理由见 `lib/index.js` 的\n * `refreshPreference()` 注释。因此映射表只有四条，不多不少。\n */\n\n/** 语言模式：自动跟随界面语言 */\nexport const MODE_AUTO = 'auto';\n\n/** 语言模式：固定使用 `targetLanguage` */\nexport const MODE_MANUAL = 'manual';\n\n/**\n * 语言模式的「未选择」哨兵值。\n *\n * 为什么默认值是空串而不是 `'auto'`：`readField(config, 'languageMode')` 读到的是\n * **已经过 schema 解析**的值，只要写了 `.default('auto')` 就永远无法区分\n * 「用户显式选了自动」与「用户从没设置过」。而这两者必须区分 ——\n * 0.1.x 用户可能手选过 `targetLanguage: ja`，升级后若一律按 auto 处理，\n * 界面语言 `zh` 会把 `ja` 静默覆盖成 `zh-CN`，那是破坏性升级。\n *\n * 三态判定见 {@link effectiveMode}。\n */\nexport const MODE_UNSET = '';\n\n/** 与 Config.targetLanguage 的 pattern 同一条正则（01-mechanism.md 4.1） */\nconst BCP47 = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/;\n\n/**\n * 归一化一个语言标识：去首尾空白、下划线转连字符、校验 BCP-47。\n *\n * 下划线格式必须处理：macOS 的 `AppleLocale` 给 `zh_CN`，`AppleLanguages` 给\n * `zh-Hans-CN`（04-auto-language.md 7.3 节的实测表）。虽然 0.2.0 的 Host 侧\n * 只读 `locale.preference`（永远是 DSH 的语言包 id），但归一化放在这里可以让\n * Client 侧与未来的系统语言路径共用同一套规则。\n *\n * @param {unknown} raw 原始标识\n * @returns {string | null} 合法标识，或 null\n */\nexport function normalizeLocaleId(raw) {\n  if (typeof raw !== 'string') return null;\n  const text = raw.trim().replace(/_/g, '-');\n  if (!text) return null;\n  return BCP47.test(text) ? text : null;\n}\n\n/**\n * 把界面语言（或外部语言包 id）映射成 `targetLanguage`。\n *\n * 映射表只有四条（票 #14 裁决二）：\n *\n * | 输入 | 输出 | 依据 |\n * | --- | --- | --- |\n * | `zh` | `zh-CN` | 官方两处先例都把 `zh*` 定为简体：`dsh-client-locale/lib/client.js:1174`、`/lib/main.js:7607-7616` |\n * | `en` | `en` | `FALLBACK_LOCALE = 'en'`，且正则接受裸 `en` |\n * | 其他合法 id（`ja` / `ko` / 外部语言包） | 原样透传 | 外部语言包 id 本身就是合法 BCP-47 |\n * | 缺失 / 空串 / 非法 | `null`（由调用方兜底） | 不编造假信号 |\n *\n * **不做的事**：不猜繁简。DSH 内置语言只有 `zh` / `en`，`zh` 不区分简繁；\n * 0.2.0 也没有系统语言信号可用。繁体用户请把 `languageMode` 设为 `manual`\n * 并手动选 `zh-TW`（README 与设置卡片都写明了这条）。\n *\n * @param {unknown} preference 界面语言 id\n * @returns {string | null}\n */\nexport function mapPreference(preference) {\n  const id = normalizeLocaleId(preference);\n  if (!id) return null;\n  const primary = id.split('-')[0].toLowerCase();\n  if (primary === 'zh') return 'zh-CN';\n  if (primary === 'en') return 'en';\n  return id;\n}\n\n/**\n * 判定**有效模式**（三态 → 两态）。\n *\n * | `languageMode` | `targetLanguage` | 有效模式 | 理由 |\n * | --- | --- | --- | --- |\n * | `'auto'` | 任意 | `auto` | 用户显式选了自动 |\n * | `'manual'` | 任意 | `manual` | 用户显式选了手动 |\n * | `''`（未设） | 等于默认值 | `auto` | 从没改过语言 → 跟随界面语言 |\n * | `''`（未设） | 不等于默认值 | `manual` | **老用户手选过语言 → 尊重既有选择，绝不覆盖** |\n *\n * 最后一行是 0.2.0 的**迁移规则**：0.1.x 的 `cordis.patch.yml` 里可能写着\n * `targetLanguage: ja` 而没有 `languageMode`，升级后必须继续用 `ja`。\n *\n * @param {{ languageMode?: unknown, targetLanguage?: unknown, defaultLanguage?: string }} input\n * @returns {'auto' | 'manual'}\n */\nexport function effectiveMode({ languageMode, targetLanguage, defaultLanguage = 'zh-CN' }) {\n  const mode = typeof languageMode === 'string' ? languageMode.trim().toLowerCase() : '';\n  if (mode === MODE_MANUAL) return MODE_MANUAL;\n  if (mode === MODE_AUTO) return MODE_AUTO;\n  // 未设置：只有「用户从没改过 targetLanguage」才按自动处理\n  const target = normalizeLocaleId(targetLanguage) ?? defaultLanguage;\n  return target === defaultLanguage ? MODE_AUTO : MODE_MANUAL;\n}\n\n/**\n * 解析最终生效的 `targetLanguage`。\n *\n * 优先级（04-auto-language.md 6.1 判定链的 0.2.0 子集）：\n *\n * ```\n * manual 态 → targetLanguage（默认 zh-CN）\n * auto   态 → mapPreference(preference) ?? targetLanguage（默认 zh-CN）\n * ```\n *\n * `preference` 读不到时**退化为配置值**，不猜 `en-US`、不读 `Intl`、不起子进程\n * （04-auto-language.md 第 4 节的结论：Host 侧没有任何可靠的系统语言信号）。\n *\n * @param {{ mode?: unknown, preference?: unknown, fallback?: unknown, defaultLanguage?: string }} input\n *   `mode` 是**原始的** `languageMode` 值（可以是 `''`），不是 `effectiveMode()` 的结果 ——\n *   本函数内部会先做三态判定，保证「老用户迁移」规则在任何调用点都生效。\n * @returns {string} 合法 BCP-47 标签\n */\nexport function resolveTargetLanguage({ mode, preference, fallback, defaultLanguage = 'zh-CN' }) {\n  const base = normalizeLocaleId(fallback) ?? defaultLanguage;\n  const effective = effectiveMode({ languageMode: mode, targetLanguage: fallback, defaultLanguage });\n  if (effective === MODE_MANUAL) return base;\n  return mapPreference(preference) ?? base;\n}\n\n/**\n * 解析来源，用于 UI 上「为什么是这个语言」那一行。\n *\n * - `ui`：来自界面语言（`preference` 映射成功）\n * - `fallback`：没识别到，用了 `targetLanguage` 配置值\n * - `manual`：手动模式，不做识别\n *\n * @param {{ mode?: unknown, preference?: unknown, fallback?: unknown, defaultLanguage?: string }} input\n * @returns {'manual' | 'ui' | 'fallback'}\n */\nexport function resolveSource({ mode, preference, fallback, defaultLanguage = 'zh-CN' }) {\n  const effective = effectiveMode({ languageMode: mode, targetLanguage: fallback, defaultLanguage });\n  if (effective === MODE_MANUAL) return 'manual';\n  return mapPreference(preference) ? 'ui' : 'fallback';\n}\n"
    },
    {
      "path": "lib/commands.js",
      "content": "/**\n * `/language` 斜杠命令：输入框里的快捷方式。\n *\n * 它**不是**面板上的「快速语言切换」——那个由 client.js 的侧栏按钮承担\n * （docs/decisions/03-manifest.md 第 2.2 节）。命令的作用是「不打开设置页、\n * 不改配置文件，临时切换本会话的语言」，因此只写内存覆盖值，不写 Config。\n *\n * `commands` 服务用 `ctx.inject` 懒注册：缺该服务的部署（无交互 UI 的 headless\n * 场景）不该让插件永久 pending，否则 system prompt 的 section 永远不会注册。\n */\n\nimport { clearLanguageOverride, setLanguageOverride } from './state.js';\nimport { languageLabel } from './text.js';\n\n/** 与 Config.targetLanguage 的 pattern 保持同一正则（01-mechanism.md 4.1） */\nconst BCP47 = /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/;\n\n/** 把解析来源翻译成给人看的一句话 */\nfunction sourceHint(source) {\n  if (source === 'ui') return '跟随界面语言';\n  if (source === 'fallback') return '未识别到界面语言，用配置值兜底';\n  return '手动模式';\n}\n\n/**\n * 注册 `/language` 命令。\n *\n * 与自动模式的关系：命令写的是**内存覆盖值**，优先级高于自动解析与配置值，\n * 两种模式下都生效；`reset` 清除覆盖后回到当前模式的解析结果。命令本身\n * **不写配置**，所以不会改变 `languageMode` —— 自动模式不会因为一次临时\n * 切换就被静默改成手动（票 #14 禁止项）。\n *\n * @param {any} ctx 插件根上下文\n * @param {{\n *   language: () => string,\n *   configured: () => string,\n *   mode?: () => 'auto' | 'manual',\n *   source?: () => 'manual' | 'ui' | 'fallback',\n * }} options\n */\nexport function registerCommands(ctx, { language, configured, mode, source }) {\n  ctx.inject(['commands'], (child) => {\n    child.effect(\n      () =>\n        child.commands.register({\n          name: 'language',\n          description: '切换本会话的目标语言（只影响当前进程，不写入配置）',\n          input: { hint: '<语言标签，如 ja；reset 恢复配置值>' },\n          handler: ({ rawInput }) => {\n            const raw = typeof rawInput === 'string' ? rawInput.trim() : '';\n\n            if (!raw) {\n              const current = language();\n              const saved = configured();\n              const currentMode = typeof mode === 'function' ? mode() : 'manual';\n              const origin =\n                currentMode === 'manual'\n                  ? '手动模式'\n                  : `自动模式，${sourceHint(typeof source === 'function' ? source() : 'ui')}`;\n              const suffix =\n                currentMode === 'auto' && current !== saved ? `（配置值：${saved}）` : '';\n              return {\n                kind: 'success',\n                text: `当前目标语言：${languageLabel(current)}（${current}）· ${origin}${suffix}`,\n              };\n            }\n\n            if (raw === 'reset' || raw === 'default') {\n              clearLanguageOverride();\n              const restored = language();\n              const currentMode = typeof mode === 'function' ? mode() : 'manual';\n              const where = currentMode === 'manual' ? '配置中的目标语言' : '自动解析结果';\n              return {\n                kind: 'success',\n                text: `已恢复为${where}：${languageLabel(restored)}（${restored}）`,\n              };\n            }\n\n            if (!BCP47.test(raw)) {\n              return {\n                kind: 'error',\n                text: `不是合法的 BCP-47 语言标签：${raw}（示例：zh-CN、zh-TW、en、ja、ko）`,\n              };\n            }\n\n            setLanguageOverride(raw);\n            return {\n              kind: 'success',\n              text: `本会话目标语言已切换为 ${languageLabel(raw)}（${raw}），下一条消息起生效。`,\n            };\n          },\n        }),\n      'language-guard: /language command',\n    );\n  });\n}\n"
    }
